const listFailingLandingRevisionChecks = `-- name: ListFailingLandingRevisionChecks :many
SELECT requested.context::text AS context
FROM jsonb_each_text($1::jsonb) AS revision
CROSS JOIN unnest($2::text[]) AS requested(context)
LEFT JOIN LATERAL (
    SELECT cs.status
    FROM commit_statuses cs
    WHERE cs.repository_id = $3
      AND cs.commit_sha = revision.value
      AND (cs.change_id = revision.key OR cs.change_id IS NULL)
      AND cs.context = requested.context
    ORDER BY cs.created_at DESC, cs.id DESC
    LIMIT 1
) AS latest ON true
GROUP BY requested.context
HAVING NOT bool_and(COALESCE(latest.status = 'success', false))
ORDER BY requested.context
`

type ListFailingLandingRevisionChecksParams struct {
	Revisions    json.RawMessage `json:"revisions"`
	Contexts     []string        `json:"contexts"`
	RepositoryID int64           `json:"repository_id"`
}

// A required context must succeed on EVERY immutable revision in the stack.
// Missing statuses and success on an older rewrite never authorize landing.
func (q *Queries) ListFailingLandingRevisionChecks(ctx context.Context, arg ListFailingLandingRevisionChecksParams) ([]string, error) {
	rows, err := q.db.Query(ctx, listFailingLandingRevisionChecks, arg.Revisions, arg.Contexts, arg.RepositoryID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var context string
		if err := rows.Scan(&context); err != nil {
			return nil, err
		}
		items = append(items, context)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

