const markWorkflowRunSuperseded = `-- name: MarkWorkflowRunSuperseded :exec
UPDATE workflow_runs
SET cancel_reason = $1,
    updated_at = NOW()
WHERE id = $2
  AND status = 'cancelled'
  AND cancel_reason = ''
`

type MarkWorkflowRunSupersededParams struct {
	CancelReason string `json:"cancel_reason"`
	ID           int64  `json:"id"`
}

// Records WHY a run was cancelled. Guarded on status = 'cancelled' so a run
// that reached success/failure in the race window between the supersede scan
// and the cancel is never mislabelled, and on an empty cancel_reason so the
// first writer wins.
func (q *Queries) MarkWorkflowRunSuperseded(ctx context.Context, arg MarkWorkflowRunSupersededParams) error {
	_, err := q.db.Exec(ctx, markWorkflowRunSuperseded, arg.CancelReason, arg.ID)
	return err
}

